import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr01303Controller {
  @Post('/personnel-appointments/:personnelAppointmentId/process')
  @HttpCode(200)
  async processPersonnelAppointment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    const id = req.params['personnelAppointmentId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '인사발령 ID 형식이 올바르지 않습니다.');
    }
    let processedDate: string | null = null;
    if (data['processedDate'] !== undefined && data['processedDate'] !== null && data['processedDate'] !== '') {
      if (typeof data['processedDate'] !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(data['processedDate'])) {
        throw new ApiError(400, 'VALIDATION_FAILED', '처리일자 형식이 올바르지 않습니다.');
      }
      processedDate = data['processedDate'];
    }
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT personnel_appointment_id AS "personnelAppointmentId", employee_id AS "employeeId", status AS "status" FROM personnel_appointment WHERE personnel_appointment_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '인사발령을 찾을 수 없습니다.');
      }
      const appointment = found[0];
      if (appointment.status === '처리완료') {
        throw new ApiError(409, 'APPOINTMENT_ALREADY_PROCESSED', '이미 처리된 발령입니다.');
      }
      if (appointment.status !== '승인') {
        throw new ApiError(409, 'APPOINTMENT_NOT_APPROVED', '승인 상태가 아닌 발령은 처리할 수 없습니다.');
      }
      // 가정: 발령 효력은 처리 시점에 인사정보에 즉시 반영한다.
      const hr = await db.query(
        'UPDATE hr_record SET department_id = COALESCE((SELECT department_id FROM personnel_appointment WHERE personnel_appointment_id = CAST(:id AS bigint)), department_id), position_name = COALESCE((SELECT new_position_name FROM personnel_appointment WHERE personnel_appointment_id = CAST(:id AS bigint)), position_name), updated_at = now() WHERE employee_id = CAST(:employeeId AS bigint) RETURNING position_name AS "positionName", department_id AS "departmentId"',
        { id, employeeId: String(appointment.employeeId) },
      );
      if (hr.length === 0) {
        throw new ApiError(422, 'HR_RECORD_UPDATE_FAILED', '대상자의 인사정보가 없어 반영하지 못했습니다.');
      }
      // 가정: 처리일자 미입력 시 현재 일자
      const done = await db.query(
        'UPDATE personnel_appointment SET status = \'처리완료\', processed_by = CAST(:userId AS bigint), processed_date = COALESCE(CAST(:processedDate AS date), CAST(now() AS date)), updated_at = now() WHERE personnel_appointment_id = CAST(:id AS bigint) RETURNING status AS "status", processed_date AS "processedDate"',
        { id, userId: user.id, processedDate },
      );
      return {
        status: done[0].status,
        processedDate: done[0].processedDate,
        positionName: hr[0].positionName,
        departmentId: hr[0].departmentId,
      };
    });
  }
}

