import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  RefName,
  Tiles,
  call,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr01303Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [appointmentId, setAppointmentId] = useState<number | string>('');
  const [processedDate, setProcessedDate] = useState('');

  function openDrawer() {
    setAppointmentId('');
    setProcessedDate('');
    setOpen(true);
  }

  async function submit() {
    if (appointmentId === '') {
      throw new Error('처리할 인사발령을 선택하세요.');
    }
    const body: Row = processedDate ? { processedDate } : {};
    const res = await call('POST', `/personnel-appointments/${appointmentId}/process`, role, body);
    setResults([{ ...res, personnelAppointmentId: appointmentId }, ...results]);
    setOpen(false);
    notify('인사발령을 처리했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>처리 건수</h2>
        <Tiles items={[['이번 화면 처리', results.length]]} />
      </section>
      <section className="box span-8">
        <h2>처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={openDrawer}>인사발령 처리</button>
        </Band>
        <DataTable
          rows={results}
          empty="처리한 발령이 없습니다."
          columns={[
            {
              key: 'personnelAppointmentId',
              label: '인사발령',
              render: (r) => <RefName table="personnel_appointment" role={role} value={r.personnelAppointmentId} />,
            },
            { key: 'status', label: '발령 상태', render: (r) => <Badge value={r.status} /> },
            { key: 'processedDate', label: '처리일자', render: (r) => <DateText value={r.processedDate} /> },
            { key: 'positionName', label: '직위' },
            {
              key: 'departmentId',
              label: '소속 부서',
              render: (r) => <RefName table="department" role={role} value={r.departmentId} />,
            },
          ]}
        />
      </section>
      {open && (
        <Drawer title="인사발령 처리" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="처리" note="승인된 인사발령만 처리할 수 있습니다.">
            <Field label="인사발령" required wide>
              <LookupSelect
                table="personnel_appointment"
                role={role}
                value={appointmentId}
                onChange={setAppointmentId}
              />
            </Field>
            <Field label="처리일자" hint="비우면 오늘 날짜로 처리합니다.">
              <DateInput value={processedDate} onChange={setProcessedDate} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
